  XLSX_THUMBNAIL_MAX_ROWS,
} from "./thumbnail-limits";

export function getThumbnailOptions(
  descriptor: ViewerDescriptor,
): ThumbnailOption[] {
  switch (descriptor.category) {
    case "text":
    case "markdown":
    case "html":
      return [thumbnailOption("text-max-bytes", TEXT_THUMBNAIL_MAX_BYTES)];
    case "csv":
      return [
        thumbnailOption("text-max-bytes", TEXT_THUMBNAIL_MAX_BYTES),
        thumbnailOption("csv-max-rows", CSV_THUMBNAIL_MAX_ROWS),
        thumbnailOption("csv-max-columns", CSV_THUMBNAIL_MAX_COLUMNS),
      ];
    case "xlsx":
      return [
        thumbnailOption("xlsx-max-rows", XLSX_THUMBNAIL_MAX_ROWS),
        thumbnailOption("xlsx-max-columns", XLSX_THUMBNAIL_MAX_COLUMNS),
      ];
    case "image":
      return isTiffDescriptor(descriptor)
        ? [thumbnailOption("tiff-target-width", TIFF_THUMBNAIL_TARGET_WIDTH)]
        : [];
    default:
      return [];
  }
}

import type { ThumbnailFileMeta } from "./thumbnail-text";

/**
 * Profiling helper: logs `[thumb] <label> <ms>` when enabled. Gated on a global
 * so it costs nothing in normal use; the profiler sets it before navigation.
 */
export async function timedThumbnail<T>(
  label: string,
  fn: () => Promise<T>,
): Promise<T> {
  const on =
    typeof globalThis !== "undefined" &&
    (globalThis as { __THUMB_PROFILE__?: boolean }).__THUMB_PROFILE__;
  if (!on) return fn();
  const t0 = performance.now();
  try {
    return await fn();
  } finally {
    console.log(`[thumb] ${label} ${(performance.now() - t0).toFixed(1)}ms`);
  }
}

export function shortName(meta: ThumbnailFileMeta): string {
  return meta.fileName;
