/** Centered, clipped white surface that hosts a rendered first unit. */
export function Surface({ children }: { children: React.ReactNode }) {
  return (
    <div className="absolute inset-0 flex items-center justify-center overflow-hidden bg-white">
      {children}
    </div>
  );
}

export function useElementWidth() {
  const [width, setWidth] = React.useState<number | null>(null);
  const ref = React.useCallback((el: HTMLElement | null) => {
    if (!el) return;
    setWidth(el.clientWidth);
    const observer = new ResizeObserver((entries) => {
      const nextWidth = entries[0]?.contentRect.width;
      if (nextWidth) setWidth(nextWidth);
    });
    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  return { ref, width };
}

const GRID_COL_W = 46;

/** Internal-gridline table shared by the XLSX and CSV previews. */
export function GridTable({
  rows,
  headerRow,
}: {
  rows: string[][];
  headerRow?: boolean;
}) {
  const colCount = Math.max(1, ...rows.map((r) => r.length));
  return (
    <div className="absolute inset-0 overflow-hidden bg-white text-slate-700">
      <table
        className="border-collapse leading-tight"
        style={{
          width: colCount * GRID_COL_W,
          tableLayout: "fixed",
          fontSize: 7,
        }}
      >
        <tbody>
          {rows.map((row, r) => (
            <tr key={r}>
              {Array.from({ length: colCount }, (_, c) => (
                <td
                  key={c}
                  className={cn(
                    "truncate border-r border-b border-slate-200 px-1 py-0.5 last:border-r-0",
                    headerRow && r === 0
                      ? "bg-slate-50 font-semibold text-slate-900"
                      : "text-slate-700",
                  )}
                >
                  {row[c] ?? ""}
                </td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

/**
 * Renders an HTML string into a fixed-size (square) sandboxed iframe and scales
 * it to the measured frame width, so the top of the page fills the tile. The
 * iframe is inert (no scripts, no pointer events).
 */
export function IframeDoc({ html }: { html: string }) {
  const { ref, width } = useElementWidth();

  const BASE = 820;
  const scale = width ? width / BASE : null;

  return (
    <div ref={ref} className="absolute inset-0 overflow-hidden bg-white">
      <iframe
        srcDoc={html}
        title=""
        sandbox=""
        scrolling="no"
        tabIndex={-1}
        aria-hidden
        className="pointer-events-none origin-top-left border-0"
        style={{
          width: BASE,
          height: BASE,
          transform: scale ? `scale(${scale})` : undefined,
          visibility: scale ? "visible" : "hidden",
        }}
      />
    </div>
  );
}

"use client";

import * as React from "react";
import type * as DOMPurify from "dompurify";
import type * as Marked from "marked";

import type { ViewerResource } from "@/lib/viewer-resource";
import { IframeDoc } from "@/components/file-thumbnail/renderers/layout";
import {
  cachedThumbnailResource,
  createThumbnailArtifactCache,
} from "@/components/file-thumbnail/thumbnail-cache";
import { withThumbnailFormatError } from "@/components/file-thumbnail/thumbnail-errors";
import {
  shortName,
  timedThumbnail,
} from "@/components/file-thumbnail/thumbnail-profile";
import { useThumbnailResource } from "@/components/file-thumbnail/thumbnail-resource";
import {
  getThumbnailText,
  thumbnailFileMeta,
  type ThumbnailFileMeta,
  type ThumbnailTextContent,
} from "@/components/file-thumbnail/thumbnail-text";

let mdLibs: Promise<[typeof Marked, typeof DOMPurify]> | null = null;

function loadMarkdown() {
  if (!mdLibs) mdLibs = Promise.all([import("marked"), import("dompurify")]);
  return mdLibs;
}

const MARKDOWN_THUMBNAIL_CACHE_MAX_ENTRIES = 64;

const markdownBodyCache = createThumbnailArtifactCache<string>({
  maxEntries: MARKDOWN_THUMBNAIL_CACHE_MAX_ENTRIES,
});

type MarkdownThumbnailColorScheme = "light" | "dark";

function getMarkdownBody(
  meta: ThumbnailFileMeta,
  content: ThumbnailTextContent,
  thumbnailKey: string,
): Promise<string> {
  return cachedThumbnailResource(markdownBodyCache, thumbnailKey, () =>
    withThumbnailFormatError(
      "markdown",
      "render_failed",
      meta.fileName,
      "Failed to render markdown thumbnail",
      () =>
        timedThumbnail(`markdown:total ${shortName(meta)}`, async () => {
          const [text, [{ marked }, DOMPurifyMod]] = await Promise.all([
            getThumbnailText(meta, content, thumbnailKey),
            loadMarkdown(),
          ]);
          const purifier = DOMPurifyMod as unknown as {
            default?: { sanitize?: (html: string) => string };
            sanitize?: (html: string) => string;
          };
          const sanitize = purifier.default?.sanitize ?? purifier.sanitize;
          if (!sanitize) throw new Error("DOMPurify sanitize unavailable");
          return sanitize(await marked.parse(text));
        }),
    ),
  );
}

function createMarkdownDoc(
  body: string,
  colorScheme: MarkdownThumbnailColorScheme,
) {
  return `<!doctype html><html data-color-scheme="${colorScheme}"><head><meta charset="utf-8"><style>
        :root{color-scheme:light;--md-bg:#ffffff;--md-fg:#0f172a;--md-muted:#f1f5f9;--md-border:#e2e8f0;--md-quote:#475569;--md-link:#4f46e5}
        :root[data-color-scheme="dark"]{color-scheme:dark;--md-bg:#111113;--md-fg:#e4e4e7;--md-muted:#1f2937;--md-border:#3f3f46;--md-quote:#a1a1aa;--md-link:#a5b4fc}
        html,body{min-height:100%;background:var(--md-bg)}
        body{margin:0;padding:18px;font:14px/1.6 -apple-system,BlinkMacSystemFont,system-ui,sans-serif;color:var(--md-fg)}
        h1{font-size:1.6em;margin:.1em 0 .5em;border-bottom:1px solid var(--md-border);padding-bottom:.25em}
        h2{font-size:1.3em;margin:1em 0 .4em;border-bottom:1px solid var(--md-border);padding-bottom:.25em}
        h3{font-size:1.1em;margin:1em 0 .3em}
        p,ul,ol{margin:0 0 .8em}ul,ol{padding-left:1.4em}
        code{font-family:ui-monospace,SFMono-Regular,monospace;background:var(--md-muted);padding:.1em .35em;border-radius:4px;font-size:.85em}
        pre{background:var(--md-muted);padding:12px;border-radius:8px;overflow:hidden}pre code{background:none;padding:0}
        table{border-collapse:collapse;width:100%}td,th{border:1px solid var(--md-border);padding:4px 8px;text-align:left}
        a{color:var(--md-link)}blockquote{margin:0 0 .8em;padding-left:12px;border-left:3px solid var(--md-border);color:var(--md-quote)}
      </style></head><body>${body}</body></html>`;
}

function useMarkdownThumbnailColorScheme(): MarkdownThumbnailColorScheme {
  return React.useSyncExternalStore(
    subscribeMarkdownThumbnailColorScheme,
    getMarkdownThumbnailColorScheme,
    () => "light",
  );
}

function subscribeMarkdownThumbnailColorScheme(onChange: () => void) {
  if (
    typeof document === "undefined" ||
    typeof MutationObserver === "undefined"
  ) {
    return () => {};
  }

  const observer = new MutationObserver(onChange);
  observer.observe(document.documentElement, {
    attributes: true,
    attributeFilter: ["class"],
  });
  return () => observer.disconnect();
}

function getMarkdownThumbnailColorScheme(): MarkdownThumbnailColorScheme {
  if (
    typeof document !== "undefined" &&
    document.documentElement.classList.contains("dark")
  ) {
    return "dark";
  }
  return "light";
}

export function MarkdownFirstPage({
  resource,
  thumbnailKey,
}: {
  resource: ViewerResource;
  thumbnailKey: string;
}) {
  const colorScheme = useMarkdownThumbnailColorScheme();
  const body = useThumbnailResource(
    getMarkdownBody(
      thumbnailFileMeta(resource),
      resource.content,
      thumbnailKey,
    ),
  );
  return <IframeDoc html={createMarkdownDoc(body, colorScheme)} />;
}

"use client";

import * as React from "react";
import type MsgReader from "@kenjiuno/msgreader";
import type { FieldsData } from "@kenjiuno/msgreader";

import type {
  ViewerContentBytes,
  ViewerContentIdentity,
  ViewerResource,
} from "@/lib/viewer-resource";
import { IframeDoc } from "@/components/file-thumbnail/renderers/layout";
import {
  cachedThumbnailResource,
  createThumbnailArtifactCache,
} from "@/components/file-thumbnail/thumbnail-cache";
import { withThumbnailFormatError } from "@/components/file-thumbnail/thumbnail-errors";
import {
  TEXT_THUMBNAIL_CACHE_MAX_ENTRIES,
  TEXT_THUMBNAIL_MAX_BYTES,
} from "@/components/file-thumbnail/thumbnail-limits";
import {
  shortName,
  timedThumbnail,
} from "@/components/file-thumbnail/thumbnail-profile";
import { useThumbnailResource } from "@/components/file-thumbnail/thumbnail-resource";

type MsgReaderConstructor = new (
  arrayBuffer: ArrayBuffer | DataView,
) => MsgReader;
type MsgThumbnailContent = ViewerContentIdentity & ViewerContentBytes;

let msgReaderLib: Promise<{ default: MsgReaderConstructor }> | null = null;

const msgHtmlCache = createThumbnailArtifactCache<string>({
  maxEntries: TEXT_THUMBNAIL_CACHE_MAX_ENTRIES,
});

function loadMsgReader() {
  if (!msgReaderLib) {
    msgReaderLib = import("@kenjiuno/msgreader") as Promise<{
      default: MsgReaderConstructor;
    }>;
  }
  return msgReaderLib;
}

export function MsgEmailThumbnail({
  resource,
  thumbnailKey,
}: {
  resource: ViewerResource;
  thumbnailKey: string;
}) {
  const html = useThumbnailResource(
    getMsgThumbnailHtml(resource, resource.content, thumbnailKey),
  );

  return <IframeDoc html={html} />;
}

function getMsgThumbnailHtml(
  meta: Pick<ViewerResource, "fileName" | "sourceKind">,
  content: MsgThumbnailContent,
  thumbnailKey: string,
): Promise<string> {
  return cachedThumbnailResource(msgHtmlCache, thumbnailKey, () =>
    withThumbnailFormatError(
      "email",
      "parse_failed",
      meta.fileName,
      "Failed to parse MSG thumbnail",
      () =>
        timedThumbnail(`msg:parse ${shortName(meta)}`, async () => {
          const bytes = await content.readBytes();
          const { default: MsgReaderClass } = await loadMsgReader();
          const reader = new MsgReaderClass(bytes.slice(0));
          const fields = reader.getFileData();
          if (fields.error) throw new Error(fields.error);
          return msgFieldsToHtml(fields);
        }),
    ),
  );
}

export function msgFieldsToHtml(
  fields: Pick<FieldsData, "body" | "bodyHtml" | "html">,
) {
  const bodyHtml = cleanMsgHtml(fields.bodyHtml);
  if (bodyHtml) return bodyHtml;

  if (fields.html?.byteLength) {
    const html = cleanMsgHtml(decodeMsgHtmlBytes(fields.html));
    if (html) return html;
  }

  const body = fields.body?.trim();
  if (body) return plainTextEmailHtml(body);

  throw new Error("MSG file does not contain a previewable email body.");
}

export function decodeMsgHtmlBytes(bytes: Uint8Array) {
  if (bytes[0] === 0xff && bytes[1] === 0xfe) {
    return new TextDecoder("utf-16le").decode(bytes.subarray(2));
  }
  if (bytes[0] === 0xfe && bytes[1] === 0xff) {
    return new TextDecoder("utf-16be").decode(bytes.subarray(2));
  }
  if (looksLikeUtf16Le(bytes)) return new TextDecoder("utf-16le").decode(bytes);
  return new TextDecoder("utf-8").decode(bytes);
}

function looksLikeUtf16Le(bytes: Uint8Array) {
  const sampleLength = Math.min(bytes.byteLength, TEXT_THUMBNAIL_MAX_BYTES);
  if (sampleLength < 4) return false;

  let oddNulls = 0;
  let evenNulls = 0;
  for (let index = 0; index < sampleLength; index += 1) {
    if (bytes[index] !== 0) continue;
    if (index % 2 === 0) evenNulls += 1;
    else oddNulls += 1;
  }

  return oddNulls > evenNulls * 4 && oddNulls > sampleLength / 8;
}

function cleanMsgHtml(html: string | null | undefined) {
  return html?.replace(/\0+$/g, "").trim() ?? "";
}

function plainTextEmailHtml(text: string) {
  return `<!doctype html><html><head><meta charset="utf-8" /></head><body><pre style="margin:0;white-space:pre-wrap;font:14px/1.5 system-ui,-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;color:#111827;">${escapeHtml(text)}</pre></body></html>`;
}

function escapeHtml(text: string) {
  return text
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

"use client";

import * as React from "react";

import type { PdfDocumentProxy } from "@/lib/pdf-document-types";
import {
  getPdfDocumentResource,
  getPdfPageResource,
} from "@/lib/pdf-document-resource";
import { cn } from "@/lib/utils";
import type { ViewerResource } from "@/lib/viewer-resource";
import { withThumbnailFormatError } from "@/components/file-thumbnail/thumbnail-errors";
import { useThumbnailResource } from "@/components/file-thumbnail/thumbnail-resource";
import type { ThumbnailAnchor } from "@/components/file-thumbnail/types";
import { ANCHOR_CORNER } from "@/components/file-thumbnail/types";

// Page 1 via pdfjs, reusing the PdfViewer's cached document.
export function PdfFirstPage({
  resource,
  anchor,
}: {
  resource: ViewerResource;
  anchor: ThumbnailAnchor;
}) {
  const doc = useThumbnailResource(
    getPdfDocumentResource(resource.content),
  ) as PdfDocumentProxy;
  const page = useThumbnailResource(getPdfPageResource(doc, 1));
  const [renderError, setRenderError] = React.useState<unknown>(null);

  const RENDER_W = 520;
  const viewport = React.useMemo(() => {
    const base = page.getViewport({ scale: 1 });
    return page.getViewport({ scale: RENDER_W / base.width });
  }, [page]);
  const dpr =
    (typeof window !== "undefined" ? window.devicePixelRatio : 1) || 1;

  if (renderError) throw renderError;

  const canvasRef = React.useCallback(
    (canvas: HTMLCanvasElement | null) => {
      if (!canvas) return;
      const context = canvas.getContext("2d");
      if (!context) return;
      let active = true;
      canvas.width = Math.floor(viewport.width * dpr);
      canvas.height = Math.floor(viewport.height * dpr);
      const task = page.render({
        canvas,
        canvasContext: context,
        viewport,
        transform: dpr !== 1 ? [dpr, 0, 0, dpr, 0, 0] : undefined,
      });
      void withThumbnailFormatError(
        "pdf",
        "render_failed",
        resource.fileName,
        "Failed to render PDF thumbnail",
        () => task.promise,
      ).catch((error: unknown) => {
        if (active) setRenderError(error);
      });
      return () => {
        active = false;
        task.cancel();
      };
    },
    [page, viewport, dpr, resource.fileName],
  );

  return (
    <div className="absolute inset-0 overflow-hidden bg-white">
      <canvas
        ref={canvasRef}
        className={cn("absolute block w-full", ANCHOR_CORNER[anchor])}
      />
    </div>
  );
}

"use client";

import * as React from "react";
import { useMountEffect } from "@/hooks/use-mount-effect";

import { cn } from "@/lib/utils";
import type { ViewerResource } from "@/lib/viewer-resource";
import { getPptxSource } from "@/components/ui/pptx-viewer-source";
import {
  cachedThumbnailResource,
  createThumbnailArtifactCache,
} from "@/components/file-thumbnail/thumbnail-cache";
import { withThumbnailDecodeSlot } from "@/components/file-thumbnail/thumbnail-decode-queue";
import { withThumbnailFormatError } from "@/components/file-thumbnail/thumbnail-errors";
import {
  shortName,
  timedThumbnail,
} from "@/components/file-thumbnail/thumbnail-profile";
import { useThumbnailResource } from "@/components/file-thumbnail/thumbnail-resource";
import {
  thumbnailFileMeta,
  type ThumbnailBytesContent,
  type ThumbnailFileMeta,
} from "@/components/file-thumbnail/thumbnail-text";
import type { ThumbnailAnchor } from "@/components/file-thumbnail/types";
import { ANCHOR_CORNER } from "@/components/file-thumbnail/types";

interface PptxFirstSlideSource {
  render: (canvas: HTMLCanvasElement, scale: number) => Promise<void>;
  baseWidth: number;
  baseHeight: number;
  dispose?: () => void;
}

const pptxCache = createThumbnailArtifactCache<PptxFirstSlideSource>({
  maxEntries: 4,
  dispose: (source) => source.dispose?.(),
});

function getPptxFirstSlide(
  meta: ThumbnailFileMeta,
  content: ThumbnailBytesContent,
  thumbnailKey: string,
): Promise<PptxFirstSlideSource> {
  return cachedThumbnailResource(pptxCache, thumbnailKey, () =>
    withThumbnailDecodeSlot(() =>
      withThumbnailFormatError(
        "pptx",
        "parse_failed",
        meta.fileName,
        "Failed to parse presentation thumbnail",
        () =>
          timedThumbnail(`pptx:total ${shortName(meta)}`, async () => {
            const source = await getPptxSource(content);
            const release = source.retain();
            const render = async (canvas: HTMLCanvasElement, scale: number) => {
              await withThumbnailFormatError(
                "pptx",
                "render_failed",
                meta.fileName,
                "Failed to render presentation thumbnail",
                async () => {
                  const result = await source.renderSlide({
                    canvas,
                    renderScale: scale,
                    slideIndex: 0,
                    priority: {
                      distanceFromReadingMarker: 0,
                      isCurrentSlide: true,
                      isInViewport: true,
                    },
                  });
                  if (result.status === "failed") throw result.error;
                },
              );
            };
            return {
              render,
              baseWidth: source.baseSize.width,
              baseHeight: source.baseSize.height,
              dispose: release,
            };
          }),
      ),
    ),
  );
}

export function PptxFirstSlide({
  resource,
  thumbnailKey,
  anchor,
}: {
  resource: ViewerResource;
  thumbnailKey: string;
  anchor: ThumbnailAnchor;
}) {
  useMountEffect(() => {
    const preload = () => {
      void import("@/components/ui/pptx-viewer").then((module) => {
        module.preloadPptxViewer();
      });
    };
    if (typeof window.requestIdleCallback === "function") {
      const id = window.requestIdleCallback(preload);
      return () => window.cancelIdleCallback(id);
    }
    const id = window.setTimeout(preload, 0);
    return () => window.clearTimeout(id);
  });

  const source = useThumbnailResource(
    getPptxFirstSlide(
      thumbnailFileMeta(resource),
      resource.content,
      thumbnailKey,
    ),
  );
  const [renderError, setRenderError] = React.useState<unknown>(null);
  const baseW = source.baseWidth || 960;
  const baseH = source.baseHeight || 720;
  const FILL_PX = 1024;
  const scale = FILL_PX / Math.min(baseW, baseH);

  if (renderError) throw renderError;

  const canvasRef = React.useCallback(
    (canvas: HTMLCanvasElement | null) => {
      if (!canvas) return;
      let active = true;
      source.render(canvas, scale).catch((error: unknown) => {
        if (active) setRenderError(error);
      });
      return () => {
        active = false;
      };
    },
    [source, scale],
  );

  const landscape = baseW >= baseH;
  return (
    <div className="absolute inset-0 overflow-hidden bg-white">
      <canvas
        ref={canvasRef}
        className={cn(
          "absolute block",
          ANCHOR_CORNER[anchor],
          landscape ? "h-full w-auto max-w-none" : "h-auto w-full",
        )}
        style={{ aspectRatio: `${baseW} / ${baseH}` }}
      />
    </div>
  );
}

"use client";

import * as React from "react";

import type { ViewerResource } from "@/lib/viewer-resource";
import { useThumbnailResource } from "@/components/file-thumbnail/thumbnail-resource";
import {
  getThumbnailText,
  thumbnailFileMeta,
} from "@/components/file-thumbnail/thumbnail-text";

const TEXT_THUMBNAIL_MAX_PARAGRAPHS = 12;
const TEXT_THUMBNAIL_FONT_SIZE = 7;
const TEXT_THUMBNAIL_LINE_HEIGHT = 1.55;

export function TextThumbnail({
  resource,
  thumbnailKey,
}: {
  resource: ViewerResource;
  thumbnailKey: string;
}) {
  const raw = useThumbnailResource(
    getThumbnailText(
      thumbnailFileMeta(resource),
      resource.content,
      thumbnailKey,
    ),
  );
  const paragraphs = React.useMemo(() => proseThumbnailParagraphs(raw), [raw]);

  if (!paragraphs.length) return <EmptyTextThumbnail />;

  return (
    <div
      data-slot="text-thumbnail"
      className="absolute inset-0 overflow-hidden bg-white p-3 font-sans text-slate-700"
      style={{
        fontSize: TEXT_THUMBNAIL_FONT_SIZE,
        lineHeight: TEXT_THUMBNAIL_LINE_HEIGHT,
      }}
    >
      <div className="space-y-1.5">
        {paragraphs.map((paragraph, i) => (
          <p key={i} className="text-pretty break-words">
            {paragraph}
          </p>
        ))}
      </div>
    </div>
  );
}

function EmptyTextThumbnail() {
  return (
    <div
      aria-label="Empty text file"
      data-slot="text-thumbnail-empty"
      className="absolute inset-0 bg-white"
    />
  );
}

function proseThumbnailParagraphs(text: string) {
  return text
    .replace(/\r\n?/g, "\n")
    .trim()
    .split(/\n{2,}/)
    .map((paragraph) => paragraph.replace(/\s*\n\s*/g, " ").trim())
    .filter(Boolean)
    .slice(0, TEXT_THUMBNAIL_MAX_PARAGRAPHS);
}

"use client";

import * as React from "react";

import { cn } from "@/lib/utils";
import type { ViewerResource } from "@/lib/viewer-resource";
import { FileThumbnailShimmer } from "@/components/ui/file-thumbnail-frame";
import { useObjectUrl } from "@/components/file-thumbnail/renderers/use-object-url";
import {
  cachedThumbnailResource,
  createThumbnailArtifactCache,
} from "@/components/file-thumbnail/thumbnail-cache";
import { withThumbnailDecodeSlot } from "@/components/file-thumbnail/thumbnail-decode-queue";
import {
  createThumbnailImageLoadError,
  withThumbnailFormatError,
} from "@/components/file-thumbnail/thumbnail-errors";
import { TIFF_THUMBNAIL_TARGET_WIDTH } from "@/components/file-thumbnail/thumbnail-limits";
import {
  shortName,
  timedThumbnail,
} from "@/components/file-thumbnail/thumbnail-profile";
import { useThumbnailResource } from "@/components/file-thumbnail/thumbnail-resource";
import {
  thumbnailFileMeta,
  type ThumbnailBytesContent,
  type ThumbnailFileMeta,
} from "@/components/file-thumbnail/thumbnail-text";
import {
  createThumbnailWorkerClient,
  type ThumbnailWorkerMessage,
} from "@/components/file-thumbnail/thumbnail-worker-client";
import type { ThumbnailAnchor } from "@/components/file-thumbnail/types";
import { ANCHOR_CORNER } from "@/components/file-thumbnail/types";

interface TiffWorkerRequest extends ThumbnailWorkerMessage {
  buffer: ArrayBuffer;
  targetWidth: number;
}

interface TiffWorkerReply extends ThumbnailWorkerMessage {
  id: number;
  ok: boolean;
  blob?: Blob;
  error?: string;
}

const tiffWorkerClient = createThumbnailWorkerClient<
  TiffWorkerRequest,
  TiffWorkerReply
>({
  createWorker: () =>
    new Worker(new URL("../../file-thumbnail-tiff.worker", import.meta.url)),
  resolve: (response) =>
    response.ok && response.blob ? response.blob : undefined,
  reject: (response) => response.error ?? "TIFF decode failed",
});

function decodeTiffInWorker(buffer: ArrayBuffer): Promise<Blob> {
  return tiffWorkerClient.request<Blob>({
    request: { buffer, targetWidth: TIFF_THUMBNAIL_TARGET_WIDTH },
    transfer: [buffer],
  });
}

const tiffCache = createThumbnailArtifactCache<Blob>({ maxEntries: 48 });

function getTiffFirstPageBlob(
  meta: ThumbnailFileMeta,
  content: ThumbnailBytesContent,
  thumbnailKey: string,
): Promise<Blob> {
  return cachedThumbnailResource(tiffCache, thumbnailKey, () =>
    withThumbnailDecodeSlot(() =>
      withThumbnailFormatError(
        "image",
        "decode_failed",
        meta.fileName,
        "Failed to decode TIFF thumbnail",
        () =>
          timedThumbnail(`tiff:total ${shortName(meta)}`, async () => {
            const buf = await timedThumbnail("tiff:fetch", () =>
              content.readBytes(),
            );
            return timedThumbnail("tiff:worker-decode", () =>
              decodeTiffInWorker(buf),
            );
          }),
      ),
    ),
  );
}

export function TiffFirstPage({
  resource,
  thumbnailKey,
  anchor,
  onError,
}: {
  resource: ViewerResource;
  thumbnailKey: string;
  anchor: ThumbnailAnchor;
  onError: (error: unknown) => void;
}) {
  const blob = useThumbnailResource(
    getTiffFirstPageBlob(
      thumbnailFileMeta(resource),
      resource.content,
      thumbnailKey,
    ),
  );
  return <TiffBlobImage blob={blob} anchor={anchor} onError={onError} />;
}

function TiffBlobImage({
  blob,
  anchor,
  onError,
}: {
  blob: Blob;
  anchor: ThumbnailAnchor;
  onError: (error: unknown) => void;
}) {
  const url = useObjectUrl(blob);

  if (!url) return <FileThumbnailShimmer />;

  return (
    <div className="absolute inset-0 overflow-hidden bg-white">
      <img
        src={url}
        alt=""
        className={cn("absolute block w-full", ANCHOR_CORNER[anchor])}
        onError={() => onError(createThumbnailImageLoadError())}
      />
    </div>
  );
}

"use client";

import * as React from "react";
import { useKeyedMountEffect } from "@/hooks/use-keyed-mount-effect";
import { joinEffectKey } from "@/lib/effect-key";

export function useObjectUrl(blob: Blob | null): string | null {
  const [url, setUrl] = React.useState<string | null>(null);

  useKeyedMountEffect(joinEffectKey([blob]), () => {
    if (!blob) {
      setUrl(null);
      return;
    }

    const nextUrl = URL.createObjectURL(blob);
    setUrl(nextUrl);
    return () => URL.revokeObjectURL(nextUrl);
  });

  return url;
}

"use client";

import * as React from "react";

import type { ViewerResource } from "@/lib/viewer-resource";
import { GridTable } from "@/components/file-thumbnail/renderers/layout";
import {
  cachedThumbnailResource,
  createThumbnailArtifactCache,
} from "@/components/file-thumbnail/thumbnail-cache";
import { withThumbnailDecodeSlot } from "@/components/file-thumbnail/thumbnail-decode-queue";
import { withThumbnailFormatError } from "@/components/file-thumbnail/thumbnail-errors";
import {
  XLSX_THUMBNAIL_MAX_COLUMNS,
  XLSX_THUMBNAIL_MAX_ROWS,
} from "@/components/file-thumbnail/thumbnail-limits";
import {
  shortName,
  timedThumbnail,
} from "@/components/file-thumbnail/thumbnail-profile";
import { useThumbnailResource } from "@/components/file-thumbnail/thumbnail-resource";
import {
  thumbnailFileMeta,
  type ThumbnailBytesContent,
  type ThumbnailFileMeta,
} from "@/components/file-thumbnail/thumbnail-text";
import {
  createThumbnailWorkerClient,
  type ThumbnailWorkerMessage,
} from "@/components/file-thumbnail/thumbnail-worker-client";

interface XlsxPreview {
  rows: string[][];
}

interface XlsxWorkerRequest extends ThumbnailWorkerMessage {
  buffer: ArrayBuffer;
  maxRows: number;
  maxCols: number;
}

interface XlsxWorkerReply extends ThumbnailWorkerMessage {
  id: number;
  ok: boolean;
  rows?: string[][];
  error?: string;
}

const xlsxWorkerClient = createThumbnailWorkerClient<
  XlsxWorkerRequest,
  XlsxWorkerReply
>({
  createWorker: () =>
    new Worker(new URL("../../file-thumbnail-xlsx.worker", import.meta.url)),
  resolve: (response) =>
    response.ok && response.rows ? response.rows : undefined,
  reject: (response) => response.error ?? "XLSX parse failed",
});

function parseXlsxInWorker(buffer: ArrayBuffer): Promise<string[][]> {
  return xlsxWorkerClient.request<string[][]>({
    request: {
      buffer,
      maxRows: XLSX_THUMBNAIL_MAX_ROWS,
      maxCols: XLSX_THUMBNAIL_MAX_COLUMNS,
    },
    transfer: [buffer],
  });
}

const xlsxCache = createThumbnailArtifactCache<XlsxPreview>({
  maxEntries: 64,
});

function getXlsxPreview(
  meta: ThumbnailFileMeta,
  content: ThumbnailBytesContent,
  thumbnailKey: string,
): Promise<XlsxPreview> {
  return cachedThumbnailResource(xlsxCache, thumbnailKey, () =>
    withThumbnailDecodeSlot(() =>
      timedThumbnail(`xlsx:total ${shortName(meta)}`, async () => {
        const rows = await withThumbnailFormatError(
          "xlsx",
          "parse_failed",
          meta.fileName,
          "Failed to parse spreadsheet thumbnail",
          async () => {
            const buf = await content.readBytes();
            return timedThumbnail("xlsx:worker-parse", () =>
              parseXlsxInWorker(buf),
            );
          },
        );
        return { rows };
      }),
    ),
  );
}

export function XlsxFirstSheet({
  resource,
  thumbnailKey,
}: {
  resource: ViewerResource;
  thumbnailKey: string;
}) {
  const { rows } = useThumbnailResource(
    getXlsxPreview(thumbnailFileMeta(resource), resource.content, thumbnailKey),
  );
  return <GridTable rows={rows} />;
}

// Decodes the FIRST page of a TIFF and downscales it to a thumbnail-sized PNG,
// entirely off the main thread. UTIF's decode, the RGBA conversion, the resize,
// and the PNG encode are all synchronous CPU — running them here keeps a grid of
// TIFF thumbnails from janking the UI. We only ever touch ifds[0], so a 200-page
// scan costs the same as a one-page one.
import UTIF from "utif";

interface Ifd {
  t256?: number[];
  t257?: number[];
  width?: number;
  height?: number;
}
interface Utif {
  decode(buf: ArrayBuffer): Ifd[];
  decodeImage(buf: ArrayBuffer, ifd: Ifd): void;
  toRGBA8(ifd: Ifd): Uint8Array;
}
const utif = UTIF as Utif;

interface Req {
  id: number;
  buffer: ArrayBuffer;
  targetWidth: number;
}

const ctx = self as unknown as Worker;

ctx.onmessage = async (event: MessageEvent<Req>) => {
  const { id, buffer, targetWidth } = event.data;
  try {
    const ifds = utif.decode(buffer);
    if (!ifds.length) throw new Error("TIFF has no frames");
    const ifd = ifds[0];
    utif.decodeImage(buffer, ifd);
    const rgba = utif.toRGBA8(ifd);
    const width = ifd.t256?.[0] ?? ifd.width ?? 0;
    const height = ifd.t257?.[0] ?? ifd.height ?? 0;
    if (!width || !height) throw new Error("TIFF has no dimensions");

    const dw = Math.min(width, targetWidth);
    const dh = Math.max(1, Math.round((dw / width) * height));
    const pixels = new Uint8ClampedArray(rgba.length);
    pixels.set(rgba);
    const source = new ImageData(pixels, width, height);
    const bitmap = await createImageBitmap(source, {
      resizeWidth: dw,
      resizeHeight: dh,
      resizeQuality: "high",
    });
    const canvas = new OffscreenCanvas(dw, dh);
    const c = canvas.getContext("2d");
    if (!c) throw new Error("No 2d context");
    c.drawImage(bitmap, 0, 0);
    bitmap.close();
    const blob = await canvas.convertToBlob({ type: "image/png" });
    ctx.postMessage({ id, ok: true, blob });
  } catch (err) {
    ctx.postMessage({
      id,
      ok: false,
      error: err instanceof Error ? err.message : String(err),
    });
  }
};

// Parses the first rows of a spreadsheet's first sheet off the main thread.
// XLSX.read is fully synchronous CPU and was the largest UI-thread block of the
// thumbnail grid; running it here keeps the page responsive. `sheetRows` stops
// the parser early so a 100k-row workbook costs the same as a 16-row one.
import * as XLSX from "@e965/xlsx";

import { isSpreadsheetContainer } from "@/lib/xlsx-worker-protocol";

interface Req {
  id: number;
  buffer: ArrayBuffer;
  maxRows: number;
  maxCols: number;
}

const ctx = self as unknown as Worker;

ctx.onmessage = (event: MessageEvent<Req>) => {
  const { id, buffer, maxRows, maxCols } = event.data;
  try {
    // SheetJS sniffs arbitrary bytes into a stub sheet; reject non-spreadsheet
    // input so a mislabeled file yields no thumbnail rather than junk cells.
    if (!isSpreadsheetContainer(buffer)) {
      throw new Error("File is not a recognized spreadsheet (.xlsx or .xls).");
    }
    const wb = XLSX.read(new Uint8Array(buffer), {
      type: "array",
      sheetRows: maxRows,
    });
    const ws = wb.Sheets[wb.SheetNames[0]];
    const grid = XLSX.utils.sheet_to_json<string[]>(ws, {
      header: 1,
      blankrows: false,
      defval: "",
      raw: false,
    });
    const rows = grid
      .slice(0, maxRows)
      .map((r) =>
        Array.isArray(r) ? r.slice(0, maxCols).map((c) => `${c ?? ""}`) : [],
      );
    ctx.postMessage({ id, ok: true, rows });
  } catch (err) {
    ctx.postMessage({
      id,
      ok: false,
      error: err instanceof Error ? err.message : String(err),
    });
  }
};

"use client";

import * as React from "react";

import type { ViewerResource } from "@/lib/viewer-resource";
import { formatCodeThumbnailText } from "@/components/file-thumbnail/thumbnail-code";
import { useThumbnailResource } from "@/components/file-thumbnail/thumbnail-resource";
import {
  getThumbnailText,
  thumbnailFileMeta,
} from "@/components/file-thumbnail/thumbnail-text";

const CODE_THUMBNAIL_MAX_LINES = 60;
const CODE_THUMBNAIL_FONT_SIZE = 5;
const CODE_THUMBNAIL_LINE_HEIGHT = 1.5;
const CODE_THUMBNAIL_LINE_NUMBER_WIDTH_CLASS = "w-2.5";

export function CodeThumbnail({
  resource,
  thumbnailKey,
}: {
  resource: ViewerResource;
  thumbnailKey: string;
}) {
  const raw = useThumbnailResource(
    getThumbnailText(
      thumbnailFileMeta(resource),
      resource.content,
      thumbnailKey,
    ),
  );
  const text = React.useMemo(
    () => formatCodeThumbnailText(raw, resource.fileName, resource.mimeType),
    [raw, resource.fileName, resource.mimeType],
  );
  const lines = React.useMemo(
    () =>
      text
        .replace(/\r?\n$/, "")
        .split(/\r\n?|\n/)
        .slice(0, CODE_THUMBNAIL_MAX_LINES),
    [text],
  );

  return (
    <div
      data-slot="code-thumbnail"
      className="bg-code text-code-foreground absolute inset-0 overflow-hidden"
    >
      <div
        aria-hidden
        className={`absolute inset-y-0 left-0 ${CODE_THUMBNAIL_LINE_NUMBER_WIDTH_CLASS} bg-code-highlight`}
      />
      <div
        className="relative font-mono"
        style={{
          fontSize: CODE_THUMBNAIL_FONT_SIZE,
          lineHeight: CODE_THUMBNAIL_LINE_HEIGHT,
        }}
      >
        {lines.map((line, i) => (
          <div key={i} className="flex">
            <span
              className={`${CODE_THUMBNAIL_LINE_NUMBER_WIDTH_CLASS} text-code-number shrink-0 pr-px text-right select-none`}
            >
              {i + 1}
            </span>
            <span className="pl-0.5 whitespace-pre">{line || " "}</span>
          </div>
        ))}
      </div>
    </div>
  );
}

import type { ViewerDescriptor } from "@/lib/viewer-source";
import { extensionOf } from "@/lib/viewer-source";

const CODE_THUMBNAIL_EXTENSIONS = new Set([
  "bash",
  "c",
  "cc",
  "cjs",
  "cpp",
  "cs",
  "css",
  "env",
  "go",
  "graphql",
  "h",
  "ini",
  "java",
  "js",
  "json",
  "json5",
  "jsonl",
  "jsx",
  "kt",
  "less",
  "log",
  "lua",
  "mjs",
  "ndjson",
  "php",
  "pl",
  "proto",
  "py",
  "r",
  "rb",
  "rs",
  "scala",
  "scss",
  "sh",
  "sql",
  "svelte",
  "swift",
  "toml",
  "ts",
  "tsx",
  "vue",
  "xml",
  "yaml",
  "yml",
  "zsh",
]);

export function isCodeThumbnailDescriptor(
  descriptor: ViewerDescriptor,
): boolean {
  const extension = extensionOf(descriptor.displayName);
  if (extension && CODE_THUMBNAIL_EXTENSIONS.has(extension)) return true;

  const mime = descriptor.mimeType?.toLowerCase().split(";")[0].trim();
  return (
    mime === "application/json" ||
    mime === "application/xml" ||
    mime === "text/javascript" ||
    mime === "application/javascript" ||
    Boolean(mime?.endsWith("+json") || mime?.endsWith("+xml"))
  );
}

export function formatCodeThumbnailText(
  text: string,
  fileName: string,
  mimeType?: string,
) {
  if (!isStrictJson(fileName, mimeType)) return text;

  try {
    return JSON.stringify(JSON.parse(text), null, 2);
  } catch {
    return text;
  }
}

function isStrictJson(fileName: string, mimeType?: string) {
  const extension = extensionOf(fileName);
  if (extension === "json") return true;
  if (
    extension === "json5" ||
    extension === "jsonl" ||
    extension === "ndjson"
  ) {
    return false;
  }

  const mime = mimeType?.toLowerCase().split(";")[0].trim();
  return mime === "application/json" || Boolean(mime?.endsWith("+json"));
}

// Ambient shim for the `utif` package, which ships no type declarations
// (and has no @types/utif on npm). shadcn's registry build strips leading
// comments from source files, so an inline `@ts-expect-error` above the import
// does not survive into the published item — a real declaration is required for
// a fresh consumer install to typecheck. The decode workers cast the default
// export to their own local shapes, so an opaque `any` default is sufficient.
declare module "utif" {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const UTIF: any;
  export default UTIF;
}
